import { test, expect } from '@playwright/test'
import {
  clearBrowserSession,
  gotoPageByFilePath,
  loginAsAdmin,
  waitForPageLoading
} from '../fixtures/auth-helpers.js'
import {
  dismissDriverGuide,
  isCompanyRecordChangeDetailResponse
} from '../fixtures/company-helpers.js'

/**
 * 禅道 #6372 直接验证（不依赖列表数据权限范围）：
 * 已知开发库里存在 biz_state=2（已备案）的变更单，直接用其 ID 打开 view 详情页，
 * 断言：『提交』(developer-change-submit-btn) 与『编辑』按钮都不存在，『返回』存在。
 *
 * 若详情接口对该账号无权限/无数据，会如实失败而不是跳过。
 */

const APPROVED_CHANGE_ID = process.env.BUG6372_CHANGE_ID || '2119732114756820994'

test.use({ viewport: { width: 1280, height: 720 } })

test.describe.serial('开发企业变更 - 审核后详情页无提交/编辑按钮 (直连详情 #6372)', () => {
  test.setTimeout(120000)

  test('已备案变更单 view 详情无提交/编辑按钮', async ({ page }) => {
    await clearBrowserSession(page)
    await loginAsAdmin(page)
    await waitForPageLoading(page)

    const detailPromise = page.waitForResponse(
      (r) => isCompanyRecordChangeDetailResponse(r) && r.ok(),
      { timeout: 40000 }
    )
    await gotoPageByFilePath(page, 'toB/companyRecord/detail', {
      formMode: 'view',
      id: APPROVED_CHANGE_ID
    })
    const detailResponse = await detailPromise
    const body = await detailResponse.json()
    console.log('[6372] detail response code=', body?.code, 'msg=', body?.msg)
    expect(body?.code, `变更详情接口返回码非 200: ${body?.msg}`).toBe(200)

    const data = body?.data?.companyRecordChange || body?.data || {}
    console.log('[6372] bizState=', data.bizState, 'companyName=', data.companyName)
    expect(String(data.bizState), '该变更单应处于已备案 biz_state=2').toBe('2')

    await waitForPageLoading(page)
    await dismissDriverGuide(page)

    const changeDetail = page.locator('.company-record-change-detail')
    await expect(changeDetail).toBeVisible({ timeout: 30000 })

    // 等详情渲染稳定（changeBizState 从后端回填）
    await page.waitForFunction(() => {
      const el = document.querySelector('.company-record-change-detail .operation-btn-group')
      return !!el
    }, { timeout: 20000 })
    // 给 Vue 一个渲染节拍，确保 changeBizState 已完成回填（避免初始 '0' 的瞬时闪烁误判）
    await expect
      .poll(async () => (await page.locator('.company-record-change-detail .operation-btn-group').count()) > 0, {
        timeout: 10000
      })
      .toBe(true)

    const toolbar = changeDetail.locator('.operation-btn-group').first()
    await expect(toolbar).toBeVisible({ timeout: 15000 })

    const btnTexts = await toolbar.locator('button').allInnerTexts()
    console.log('[6372] toolbar 实际按钮:', JSON.stringify(btnTexts))

    const submitBtn = page.locator('[data-testid="developer-change-submit-btn"]')
    await expect(submitBtn, '已备案详情页不应出现「提交」按钮').toHaveCount(0)

    const editBtn = toolbar.getByRole('button', { name: '编辑', exact: true })
    await expect(editBtn, '已备案详情页不应出现「编辑」按钮').toHaveCount(0)

    const backBtn = toolbar.getByRole('button', { name: '返回', exact: true })
    await expect(backBtn, '只读详情页应保留「返回」按钮').toBeVisible({ timeout: 15000 })

    await page.screenshot({
      path: test.info().outputPath('bug6372-approved-detail.png'),
      fullPage: true
    })
  })
})

